sys_ui_action.script:
//gs.info('Dyn Pri -Initial Values - Enabled: ' + current.enabled + ' + ', 'Rej_State: ' + current.rej_state);

if (current.enabled == true && current.rej_state != 'first rejection') {
    // Log the condition being executed
    //gs.info('Dyn Pri Condition 1: Setting rej_state to "first rejection"');

    // Change 'rej_state' to 'first rejection'
    current.rej_state = 'first rejection';
    current.u_rej_first = gs.getUserID();
    current.u_glide_date_time_4 = new GlideDateTime();
    current.update(); // Update the record
    action.setRedirectURL(current);

    // Log the updated values
    //gs.info('Dyn Pri Updated Values - Enabled: ' + current.enabled + ', State: ' + current.state + ', Rej_State: ' + current.rej_state);
} else if (current.rej_state == 'first rejection') {
    // Log the condition being executed
    //gs.info('Dyn Pri Condition 2: Setting rej_state to "Final Rejection" and disabling the record');

    // Change 'rej_state' to 'final rejection'
    current.rej_state = 'Final Rejection';
    current.enabled = false; // Set 'enabled' field to false


    current.u_rej_sec = gs.getUserID();
    current.u_sec_rej_time = new GlideDateTime();

    current.update(); // Update the record
    action.setRedirectURL(current);

    // Log the updated values
    //gs.info('Dyn Pri Updated Values - Enabled: ' + current.enabled + ', State: ' + current.state + ', Rej_State: ' + current.rej_state);
}
